import jenkins.*
import jenkins.model.*
import hudson.*
import hudson.model.*
import groovy.json.JsonSlurper;

def buildSpec = new JsonSlurper().parse(new File('/var/jenkins_home/workspace/Check For Updates/build-spec.json'));

def envVars= Hudson.instance.getItem("Check For Updates").lastBuild.properties.get("envVars");

Jenkins.instance.getItemByFullName("Bash_Functions")
.scheduleBuild2(0).get()


def run = Jenkins.instance.getItemByFullName("PIC-SURE Pipeline")
.scheduleBuild2(0).get()

if (run.getResult() != Result.SUCCESS) {
    throw new AbortException("PIC-SURE Pipeline failed")
}

hudson.tasks.Shell.command:
#!/bin/bash # shellcheck disable=SC2154 # stack_s3_bucket, source_s3_url, ... are provided by Jenkins set -e
# Decides, per HPDS variant, whether the dataset named in build-spec.json still has to be staged. # Outputs (read by the next SystemGroovy step): # toBeRekeyed.txt / alreadyRekeyed.txt auth variant # destigmatized_toBeRekeyed.txt / destigmatized_alreadyRekeyed.txt open variant # genomicDatasetKey.txt # "Already staged" = data/<key>/<stage_prefix>manifest.tsv exists (per-file staging) # or data/<key>/<legacy tar name> exists (legacy .tar staging).
dataset_marker="/data/hpds/pheno/datasets/"
# ListBucket on data/* is granted while HeadObject on a missing key may answer 403, so list first. key_exists() { local key="$1" out if out=$(aws s3api list-objects-v2 --bucket "${stack_s3_bucket}" --prefix "${key}" --output json 2> /dev/null); then printf '%s' "${out}" | jq -e --arg k "${key}" 'any(.Contents[]?; .Key == $k)' > /dev/null else aws s3api head-object --bucket "${stack_s3_bucket}" --key "${key}" > /dev/null 2>&1 fi }
# Commit that last changed the line of build-spec.json that holds the given field. # A boundary commit (root or shallow clone) is blamed as "^<hash>"; the marker is not part of the hash. blame_commit() { local key key=$(git blame --abbrev=39 build-spec.json | grep "$1" | cut -f 1 -d ' ') echo "${key#^}" }
# Deploy key = blame commit; must look like a git hash (7-40 hex) because it becomes an S3 key segment. deploy_key() { local key key=$(blame_commit "$1") if [ -z "${key}" ]; then echo "ERROR: no line for $1 in build-spec.json" >&2 exit 1 fi if ! [[ "${key}" =~ ^[0-9a-f]{7,40}$ ]]; then echo "ERROR: blame commit '${key}' for $1 is not a git hash" >&2 exit 1 fi echo "${key}" }
spec_url() { jq -r --arg f "$1" '.[$f] // ""' build-spec.json | tr -d '[:space:]' }
is_dataset_prefix() { case "$1" in *"${dataset_marker}"*) return 0 ;; esac return 1 }
# Dataset prefixes carry both variants in one dataset: the two URLs must be the same. auth_url=$(spec_url source_dataset_s3_url) open_url=$(spec_url source_destigmatized_dataset_s3_url) if is_dataset_prefix "${auth_url}" || is_dataset_prefix "${open_url}"; then if [ "${auth_url}" != "${open_url}" ]; then echo "ERROR: source_dataset_s3_url (${auth_url}) and source_destigmatized_dataset_s3_url (${open_url}) must be identical for a dataset prefix" >&2 exit 1 fi fi
# check_variant <field> <stage prefix> <legacy tar name> <to-be-staged file> <already-staged file> <label> check_variant() { local field="$1" stage_prefix="$2" legacy_name="$3" todo_file="$4" done_file="$5" label="$6" key key=$(deploy_key "${field}") if key_exists "data/${key}/${stage_prefix}manifest.tsv" || key_exists "data/${key}/${legacy_name}.tar"; then echo "${key}" > "${done_file}" echo "Using existing ${label} dataset (Skipping staging)." else echo "${key}" > "${todo_file}" echo "Will stage new ${label} dataset." fi }
check_variant source_dataset_s3_url javabins_rekeyed/ javabins_rekeyed toBeRekeyed.txt alreadyRekeyed.txt auth check_variant source_destigmatized_dataset_s3_url destigmatized_javabins_rekeyed/ destigmatized_javabins_rekeyed destigmatized_toBeRekeyed.txt destigmatized_alreadyRekeyed.txt open
LAST_GENOMIC_DATASET_MODIFICATION_COMMIT=$(blame_commit source_genomic_dataset_s3_url) echo "${LAST_GENOMIC_DATASET_MODIFICATION_COMMIT}" > genomicDatasetKey.txt

script.script:
import jenkins.*
import jenkins.model.*
import hudson.*
import hudson.model.*
import groovy.json.JsonSlurper;

def buildSpec = new JsonSlurper().parse(new File("/var/jenkins_home/workspace/Check For Updates/build-spec.json"));

def envVars= Hudson.instance.getItem("Check For Updates").lastBuild.properties.get("envVars");

// Stage one HPDS variant (auth|open). Anything but SUCCESS aborts before the Deployment Pipeline is scheduled.
def runImport = { String variant, String sourceUrl, String bucketHash ->
    def run = Jenkins.instance.getItemByFullName("Import_and_Rekey_HPDS_Data")
    .scheduleBuild2(0, new ParametersAction([
        new StringParameterValue("source_s3_url", sourceUrl.trim()),
        new StringParameterValue("HPDS_VARIANT", variant),
        new StringParameterValue("destination_bucket_hash", bucketHash.trim())
        ])).get()
    if (run.getResult() != Result.SUCCESS) {
        throw new AbortException("Import_and_Rekey_HPDS_Data (" + variant + ") finished " + run.getResult() + "; Deployment Pipeline not started")
    }
}

String dataset_s3_object_key ;
if(new File("/var/jenkins_home/workspace/Check For Updates/toBeRekeyed.txt").exists()){
    def bucket_hash = new File("/var/jenkins_home/workspace/Check For Updates/toBeRekeyed.txt").text
    runImport("auth", buildSpec.source_dataset_s3_url, bucket_hash)
    dataset_s3_object_key = new File("/var/jenkins_home/workspace/Check For Updates/toBeRekeyed.txt").text
} else {
    dataset_s3_object_key = new File("/var/jenkins_home/workspace/Check For Updates/alreadyRekeyed.txt").text
}

String destigmatized_dataset_s3_object_key ;
if(new File("/var/jenkins_home/workspace/Check For Updates/destigmatized_toBeRekeyed.txt").exists()){
    def bucket_hash = new File("/var/jenkins_home/workspace/Check For Updates/destigmatized_toBeRekeyed.txt").text
    runImport("open", buildSpec.source_destigmatized_dataset_s3_url, bucket_hash)
    destigmatized_dataset_s3_object_key = new File("/var/jenkins_home/workspace/Check For Updates/destigmatized_toBeRekeyed.txt").text
} else {
    destigmatized_dataset_s3_object_key = new File("/var/jenkins_home/workspace/Check For Updates/destigmatized_alreadyRekeyed.txt").text
}

genomic_s3_object_key = new File("/var/jenkins_home/workspace/Check For Updates/genomicDatasetKey.txt").text

Jenkins.instance.getItemByFullName("Deployment Pipeline")
    .scheduleBuild2(0, new ParametersAction([
        new StringParameterValue("deployment_git_hash", envVars["GIT_COMMIT"].trim()),
        new StringParameterValue("dataset_s3_object_key", dataset_s3_object_key.trim()),
        new StringParameterValue("destigmatized_dataset_s3_object_key", destigmatized_dataset_s3_object_key.trim()),
        new StringParameterValue("genomic_dataset_s3_object_key", genomic_s3_object_key.trim()),
])).get()
